const wc = $('When Called').first().json;
let b64 = null, sc = null, header_cost = null, err = '', fail_kind = '';
// ADR-052 Block 5: did the reference download succeed (binary reached Edit Call)? Distinguishes a fetch
// failure (dead/expired/unreachable URL) from an edit rejection, so the caller emits an actionable WARN.
let fetchOk = false;
try { const dl = $('Download Reference').first(); fetchOk = !!(dl && dl.binary && dl.binary.data); } catch (e0) { fetchOk = false; }
try {
  const r = $input.first() ? ($input.first().json || {}) : {};
  const body = (r && r.body != null) ? r.body : r;
  sc = (r && r.statusCode != null) ? r.statusCode : null;
  const data = body && body.data;
  b64 = (data && data[0] && data[0].b64_json) ? data[0].b64_json : null;
  const hdrs = (r && r.headers) ? r.headers : {};
  const ch = hdrs['x-litellm-response-cost'];
  header_cost = (ch != null && ch !== '') ? Number(ch) : null;
  if (!b64) {
    err = 'gpt-image-2-edit-no-b64' + (sc != null ? (' (HTTP ' + sc + ')') : '');
    if (!fetchOk) { fail_kind = 'fetch'; }
    else { let blob = ''; try { blob = JSON.stringify(body || {}).toLowerCase(); } catch (e1) { blob = ''; } fail_kind = /too large|too big|maximum|max size|file size|dimension|pixel|exceeds|payload/.test(blob) ? 'oversize' : 'edit'; }
  }
} catch (e) {
  err = 'shape-error: ' + ((e && e.message) ? e.message : String(e));
  fail_kind = fetchOk ? 'edit' : 'fetch';
}
return [{ json: { placeholder_id: wc.placeholder_id || '', ok: !!b64, b64_json: b64, header_cost: header_cost, statusCode: sc, error: err, fail_kind: fail_kind } }];
